--
-- Name: anchors; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.anchors (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    node_id uuid,
    kind public.anchor_kind NOT NULL,
    name text NOT NULL,
    level_id uuid,
    ordinal smallint NOT NULL,
    facing_deg real,
    surveyed_geom public.geometry(Point,4326),
    prior_source public.street_prior_source,
    prior_sigma_m real,
    photo_uri text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    rev integer DEFAULT 1 NOT NULL,
    CONSTRAINT anchors_check CHECK ((((surveyed_geom IS NULL) = (prior_source IS NULL)) AND ((surveyed_geom IS NULL) = (prior_sigma_m IS NULL)))),
    CONSTRAINT anchors_facing_deg_check CHECK (((facing_deg >= (0)::double precision) AND (facing_deg < (360)::double precision))),
    CONSTRAINT anchors_prior_sigma_m_check CHECK ((prior_sigma_m > (0)::double precision))
);

