--
-- Name: change_sets; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.change_sets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contributor_id uuid NOT NULL,
    track public.change_track NOT NULL,
    base_version_id integer,
    diff jsonb NOT NULL,
    note text,
    decision public.change_decision DEFAULT 'pending'::public.change_decision NOT NULL,
    publish_path public.publish_path,
    reviewer_id uuid,
    reviewed_at timestamp with time zone,
    map_version_id integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT change_sets_decision_matches_path CHECK (
CASE decision
    WHEN 'approved'::public.change_decision THEN (NOT (publish_path IS DISTINCT FROM 'moderator_review'::public.publish_path))
    WHEN 'auto_published'::public.change_decision THEN ((publish_path IS NOT NULL) AND (publish_path <> 'moderator_review'::public.publish_path))
    WHEN 'rolled_back'::public.change_decision THEN (publish_path IS NOT NULL)
    ELSE (publish_path IS NULL)
END),
    CONSTRAINT change_sets_status_has_no_diff CHECK (((track = 'structural'::public.change_track) OR (diff = '[]'::jsonb))),
    CONSTRAINT change_sets_version_iff_published CHECK (
CASE track
    WHEN 'status'::public.change_track THEN (map_version_id IS NULL)
    ELSE ((decision = ANY (ARRAY['approved'::public.change_decision, 'auto_published'::public.change_decision, 'rolled_back'::public.change_decision])) = (map_version_id IS NOT NULL))
END)
);

